P="""var $=function(i){return document.getElementById(i)};if(!window.ffEd){var E=window.ffEd={dirty:false,saved:'',K:'ffEditorV1'};E.ta=function(){return $('edText')};E.msg=function(m){$('edStatus').textContent=m};E.stats=function(){var v=E.ta().value,w=(v.match(/\\S+/g)||[]).length,l=v?v.split('\\n').length:0;$('edStats').textContent='Linhas '+l+' · Palavras '+w+' · Caracteres '+v.length};E.store=function(){try{localStorage.setItem(E.K,JSON.stringify({text:E.ta().value,name:$('edName').value,dark:E.dark,size:E.size}))}catch(e){}};E.changed=function(){E.dirty=E.ta().value!==E.saved;E.stats();E.msg(E.dirty?'Alterações não salvas (rascunho guardado)':'Salvo');E.store()};E.apply=function(){var t=E.ta(),bg=E.dark?'#111827':'#ffffff',fg=E.dark?'#e5e7eb':'#111827';t.style.background=bg;t.style.color=fg;t.style.fontSize=({Pequena:12,'Média':15,Grande:20})[E.size||'Média']+'px';var w=t.closest('.ff-component');if(w){w.style.background=bg;w.style.color=fg}};E.ext=function(n){n=(n||'').trim()||'sem-titulo';return /\\.[A-Za-z0-9]{1,5}$/.test(n)?n:n+'.txt'};E.find=function(){var q=$('edFind').value;if(!q){E.msg('Digite o que localizar');return false}var t=E.ta(),h=t.value.toLowerCase(),n=q.toLowerCase(),i=h.indexOf(n,t.selectionEnd);var wrapped=false;if(i<0){i=h.indexOf(n);wrapped=true}if(i<0){E.msg('Não encontrado: '+q);return false}t.focus();t.setSelectionRange(i,i+q.length);E.msg(wrapped?'Voltou ao início do texto':'Encontrado');return true};E.replace=function(){var q=$('edFind').value,t=E.ta();if(!q){E.msg('Digite o que localizar');return}var sel=t.value.slice(t.selectionStart,t.selectionEnd);if(sel.toLowerCase()===q.toLowerCase()&&sel!==''){var s=t.selectionStart;t.setRangeText($('edRepl').value,s,t.selectionEnd,'end');E.changed()}E.find()};E.replaceAll=function(){var q=$('edFind').value;if(!q){E.msg('Digite o que localizar');return}var re=new RegExp(q.replace(/[.*+?^${}()|[\\]\\\\]/g,'\\\\$&'),'gi'),t=E.ta(),n=0,r=$('edRepl').value;t.value=t.value.replace(re,function(){n++;return r});E.changed();E.msg(n+' substituição(ões)')};E.fresh=function(force){if(E.dirty&&!force&&!confirm('Descartar as alterações não salvas?'))return;E.ta().value='';$('edName').value='';E.saved='';E.dirty=false;E.stats();E.msg('Novo documento');E.store()};E.load=function(){try{var d=JSON.parse(localStorage.getItem(E.K)||'null');if(d){E.ta().value=d.text||'';$('edName').value=d.name||'';E.dark=!!d.dark;E.size=d.size||'Média';$('edDark').checked=E.dark}}catch(e){}if(!E.size)E.size='Média';$('edSize').value=E.size;E.apply();E.stats();E.msg(E.ta().value?'Rascunho restaurado':'Pronto')};E.save=function(){var name=E.ext($('edName').value);$('edName').value=name;var b=new Blob([E.ta().value],{type:'text/plain;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(a.href)},1000);E.saved=E.ta().value;E.dirty=false;E.msg('Salvo como '+name);E.store()};E.open=function(f){if(!f)return;if(E.dirty&&!confirm('Descartar as alterações não salvas?')){return}var r=new FileReader();r.onload=function(){E.ta().value=String(r.result||'');$('edName').value=f.name;E.saved=E.ta().value;E.dirty=false;E.stats();E.msg('Aberto: '+f.name);E.store()};r.onerror=function(){E.msg('Não foi possível ler o arquivo')};r.readAsText(f)};E.caseTo=function(mode){var t=E.ta(),a=t.selectionStart,b=t.selectionEnd,all=a===b,s=all?t.value:t.value.slice(a,b);var o=mode==='up'?s.toUpperCase():mode==='low'?s.toLowerCase():s.toLowerCase().replace(/(^|\\n|[.!?]\\s+)(\\p{L})/gu,function(m,p,c){return p+c.toUpperCase()});if(all)t.value=o;else t.setRangeText(o,a,b,'select');E.changed()}}"""
